import 'dart:convert';
import 'dart:typed_data';
import 'package:flutter/material.dart';

/// ============================================================================
/// FILE KHUSUS TAMPILAN & STYLE WARNA GLOBAL: tema_warna.tampilan.dart
/// Menyimpan palet warna, tema Dark UI, serta LOGO SMART KEYLESS 2FA
/// ============================================================================
class TemaWarna {
  // Palet Warna Utama (Dark Cyber Security Theme - Senada Logo Biru Smart Keyless 2FA)
  static const Color bgUtama = Color(0xFF0B0F19);
  static const Color bgKartu = Color(0xFF0F172A);
  static const Color bgInput = Color(0xFF090D16);
  static const Color garisBorder = Color(0xFF1E293B);

  // Warna Aksen & Status
  static const Color indigoUtama = Color(0xFF2563EB);
  static const Color cyanAksen = Color(0xFF00B4D8);
  static const Color hijauAman = Color(0xFF10B981);
  static const Color kuningPeringatan = Color(0xFFF59E0B);
  static const Color merahBahaya = Color(0xFFF43F5E);

  // Warna Teks
  static const Color teksPutih = Color(0xFFF8FAFC);
  static const Color teksAbu = Color(0xFF94A3B8);
  static const Color teksRedup = Color(0xFF64748B);

  // Data Gambar Logo "SMART KEYLESS 2FA" (Tertanam langsung agar tidak perlu setting pubspec.yaml)
  static const String _logoBase64 = '';
  static final Uint8List logoBytes = base64Decode(_logoBase64);

  /// Widget Logo Resmi "SMART KEYLESS 2FA"
  static Widget logoSmartKeyless({double ukuran = 42}) {
    return Container(
      width: ukuran,
      height: ukuran,
      decoration: BoxDecoration(
        shape: BoxShape.circle,
        color: Colors.white,
        boxShadow: [
          BoxShadow(
            color: cyanAksen.withValues(alpha: 0.35),
            blurRadius: 10,
            spreadRadius: 1,
          ),
        ],
      ),
      padding: const EdgeInsets.all(2),
      child: ClipOval(
        child: Image.memory(
          logoBytes,
          width: ukuran,
          height: ukuran,
          fit: BoxFit.contain,
          gaplessPlayback: true,
        ),
      ),
    );
  }

  // Tema Global MaterialApp
  static ThemeData get temaGelap {
    return ThemeData(
      useMaterial3: true,
      brightness: Brightness.dark,
      scaffoldBackgroundColor: bgUtama,
      primaryColor: indigoUtama,
      colorScheme: const ColorScheme.dark(
        primary: indigoUtama,
        secondary: cyanAksen,
        surface: bgKartu,
        error: merahBahaya,
      ),
      navigationBarTheme: NavigationBarThemeData(
        backgroundColor: bgKartu,
        indicatorColor: indigoUtama.withValues(alpha: 0.25),
        labelTextStyle: WidgetStateProperty.all(
          const TextStyle(
            fontSize: 10.5,
            fontWeight: FontWeight.w600,
            color: teksPutih,
            overflow: TextOverflow.ellipsis,
          ),
        ),
      ),
      appBarTheme: const AppBarTheme(
        backgroundColor: bgKartu,
        foregroundColor: teksPutih,
        elevation: 0,
      ),
      cardTheme: CardThemeData(
        color: bgKartu,
        elevation: 0,
        shape: RoundedRectangleBorder(
          borderRadius: BorderRadius.circular(16),
          side: const BorderSide(color: garisBorder, width: 1),
        ),
      ),
    );
  }

  // Dekorasi Kotak Kartu Glassmorphism
  static BoxDecoration dekorasiKartu({Color? warnaBorder, Color? warnaLatar}) {
    return BoxDecoration(
      color: warnaLatar ?? bgKartu,
      borderRadius: BorderRadius.circular(16),
      border: Border.all(color: warnaBorder ?? garisBorder, width: 1.2),
      boxShadow: [
        BoxShadow(
          color: Colors.black.withValues(alpha: 0.25),
          blurRadius: 12,
          offset: const Offset(0, 4),
        ),
      ],
    );
  }

  // Widget Badge Status Pill
  static Widget badgeStatus({
    required String teks,
    required Color warna,
    IconData? ikon,
  }) {
    return Container(
      padding: const EdgeInsets.symmetric(horizontal: 10, vertical: 5),
      decoration: BoxDecoration(
        color: warna.withValues(alpha: 0.15),
        borderRadius: BorderRadius.circular(99),
        border: Border.all(color: warna.withValues(alpha: 0.4)),
      ),
      child: Row(
        mainAxisSize: MainAxisSize.min,
        children: [
          if (ikon != null) ...[
            Icon(ikon, size: 13, color: warna),
            const SizedBox(width: 4),
          ],
          Text(
            teks,
            style: TextStyle(
              color: warna,
              fontSize: 11,
              fontWeight: FontWeight.w700,
            ),
          ),
        ],
      ),
    );
  }
}
